PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS cities(id TEXT PRIMARY KEY,names TEXT NOT NULL,currency TEXT NOT NULL DEFAULT 'GEL',timezone TEXT NOT NULL DEFAULT 'Asia/Tbilisi',delivery_fee INTEGER NOT NULL DEFAULT 500,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS vendors(id TEXT PRIMARY KEY,city_id TEXT NOT NULL REFERENCES cities(id),names TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,vendor_id TEXT NOT NULL REFERENCES vendors(id),names TEXT NOT NULL,category TEXT NOT NULL,art TEXT NOT NULL,profile TEXT NOT NULL,price INTEGER NOT NULL CHECK(price>=0),stock INTEGER NOT NULL CHECK(stock>=0),reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=stock),cost INTEGER CHECK(cost>=0),active INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,hash TEXT NOT NULL,salt TEXT NOT NULL,owner INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS memberships(user_id TEXT NOT NULL REFERENCES users(id),vendor_id TEXT NOT NULL REFERENCES vendors(id),role TEXT NOT NULL CHECK(role IN('ADMIN','STAFF','SUPPLIER','DRIVER')),PRIMARY KEY(user_id,vendor_id));
CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS invites(hash TEXT PRIMARY KEY,vendor_id TEXT NOT NULL REFERENCES vendors(id),role TEXT NOT NULL CHECK(role IN('ADMIN','STAFF','SUPPLIER','DRIVER')),expires INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS auth_limits(key TEXT PRIMARY KEY,attempts INTEGER NOT NULL DEFAULT 0,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS slots(city_id TEXT NOT NULL REFERENCES cities(id),day TEXT NOT NULL,minute INTEGER NOT NULL,capacity INTEGER NOT NULL DEFAULT 8,reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=capacity),PRIMARY KEY(city_id,day,minute));
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,city_id TEXT NOT NULL REFERENCES cities(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'NEW',payment TEXT NOT NULL DEFAULT 'UNPAID',currency TEXT NOT NULL,fulfillment TEXT NOT NULL,day TEXT NOT NULL,minute INTEGER NOT NULL,customer TEXT NOT NULL,quotes TEXT NOT NULL,original_quotes TEXT NOT NULL,actuals TEXT,weighing TEXT,proposal TEXT,items_total INTEGER NOT NULL,total INTEGER NOT NULL,maximum_total INTEGER NOT NULL,delivery_fee INTEGER NOT NULL,paid INTEGER NOT NULL DEFAULT 0 CHECK(paid>=0),key_hash TEXT NOT NULL,idem TEXT NOT NULL UNIQUE,fingerprint TEXT NOT NULL,driver_id TEXT REFERENCES users(id),confirmed INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(city_id,day,minute) REFERENCES slots(city_id,day,minute));
CREATE TABLE IF NOT EXISTS order_groups(order_id TEXT NOT NULL REFERENCES orders(id),vendor_id TEXT NOT NULL REFERENCES vendors(id),status TEXT NOT NULL DEFAULT 'WAITING',PRIMARY KEY(order_id,vendor_id));
CREATE TABLE IF NOT EXISTS order_lines(order_id TEXT NOT NULL REFERENCES orders(id),line_id TEXT NOT NULL,product_id TEXT NOT NULL REFERENCES products(id),vendor_id TEXT NOT NULL REFERENCES vendors(id),quote TEXT NOT NULL,cost INTEGER,reserved INTEGER NOT NULL CHECK(reserved>=0),version INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(order_id,line_id));
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),at TEXT NOT NULL,actor TEXT NOT NULL,event TEXT NOT NULL,data TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS payments(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),at TEXT NOT NULL,actor TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),currency TEXT NOT NULL,command TEXT NOT NULL UNIQUE,reason TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS commands(id TEXT PRIMARY KEY,actor TEXT NOT NULL,fingerprint TEXT NOT NULL,result TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inventory(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),at TEXT NOT NULL,actor TEXT NOT NULL,delta INTEGER NOT NULL,reason TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS expenses(id TEXT PRIMARY KEY,city_id TEXT NOT NULL REFERENCES cities(id),at TEXT NOT NULL,actor TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),category TEXT NOT NULL,reason TEXT NOT NULL,command TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS settlements(order_id TEXT PRIMARY KEY REFERENCES orders(id),expenses TEXT NOT NULL,total_expenses INTEGER NOT NULL,net INTEGER NOT NULL,required_net INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN('SHORTFALL','CLOSED')),actor TEXT NOT NULL,at TEXT NOT NULL,evidence TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),at TEXT NOT NULL,event TEXT NOT NULL,channel TEXT NOT NULL DEFAULT 'INTERNAL',status TEXT NOT NULL DEFAULT 'DISABLED',attempts INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS app_config(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS guards(value INTEGER NOT NULL CHECK(value=1));
CREATE INDEX IF NOT EXISTS products_vendor ON products(vendor_id,active);
CREATE INDEX IF NOT EXISTS orders_city ON orders(city_id,status,created_at);
CREATE INDEX IF NOT EXISTS lines_vendor ON order_lines(vendor_id,order_id);
CREATE INDEX IF NOT EXISTS events_order ON events(order_id,at);
